<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import RoomCard from '../components/RoomCard.vue'
import MapPanel from '../components/MapPanel.vue'
import {rooms,districts,amenities} from '../data'
const route=useRoute(),router=useRouter(),q=ref(route.query.q||''),district=ref(route.query.district||''),price=ref(route.query.price||''),selected=ref(route.query.amenity?[route.query.amenity]:[]),sort=ref('default'),showFilters=ref(false),showMap=ref(false)
const results=computed(()=>{let r=rooms.filter(r=>(!q.value||[r.title,r.address].join(' ').toLocaleLowerCase('vi').includes(q.value.toLocaleLowerCase('vi')))&&(!district.value||r.district===district.value)&&(!price.value||r.price<=Number(price.value))&&selected.value.every(a=>r.amenities.includes(a)));return sort.value==='asc'?[...r].sort((a,b)=>a.price-b.price):sort.value==='desc'?[...r].sort((a,b)=>b.price-a.price):r})
function reset(){q.value='';district.value='';price.value='';selected.value=[];apply()}
function apply(){router.replace({query:{q:q.value,district:district.value,price:price.value,amenity:selected.value[0]||''}});showFilters.value=false}
watch(()=>route.query,v=>{q.value=v.q||'';district.value=v.district||'';price.value=v.price||'';selected.value=v.amenity?[v.amenity]:[]})
</script>
<template><div class="container page"><div v-if="route.query.guide" class="notice"><Icon name="shield"/>Không chuyển cọc trước khi xem phòng và xác minh người cho thuê. Dữ liệu trong bản demo chỉ dùng để trải nghiệm giao diện.</div><div class="breadcrumb"><RouterLink to="/">Trang chủ</RouterLink><Icon name="right" :size="14"/>Tìm phòng trọ</div><div class="section-heading"><div><span class="eyebrow">Không gian cho cuộc sống của bạn</span><h1>Tìm phòng trọ</h1><p class="muted">Quanh trường, trong ngân sách, đúng điều bạn cần.</p></div><button class="button secondary small" @click="showMap=!showMap"><Icon :name="showMap?'grid':'map'" :size="18"/>{{showMap?'Danh sách':'Bản đồ'}}</button></div><form class="search-line" @submit.prevent="apply"><Icon name="search"/><input v-model="q" placeholder="Tìm theo tên phòng, đường, khu vực…" aria-label="Từ khóa"><button class="button primary small">Tìm kiếm</button><button type="button" class="button secondary small mobile-filter" @click="showFilters=!showFilters"><Icon name="filter"/>Bộ lọc</button></form><div class="search-layout"><aside class="filter-panel" :class="{open:showFilters}" aria-label="Bộ lọc phòng trọ"><div class="section-heading"><h3>Bộ lọc</h3><button class="text-button" @click="reset">Đặt lại</button></div><label class="field"><span>Địa điểm</span><select v-model="district"><option value="">Tất cả khu vực</option><option v-for="d in districts" :key="d">{{d}}</option></select></label><label class="field"><span>Khoảng giá</span><select v-model="price"><option value="">Tất cả mức giá</option><option value="1500000">Đến 1,5 triệu / tháng</option><option value="2000000">Đến 2 triệu / tháng</option><option value="3000000">Đến 3 triệu / tháng</option></select></label><h4>Tiện ích</h4><label v-for="a in amenities" :key="a" class="check"><input type="checkbox" :value="a" v-model="selected">{{a}}</label><button class="button primary full" @click="apply">Áp dụng bộ lọc <Icon name="arrow" :size="17"/></button></aside><section><div class="results-bar"><p><strong>{{results.length}}</strong> phòng phù hợp <span class="muted">tại Cần Thơ</span></p><select v-model="sort" aria-label="Sắp xếp kết quả"><option value="default">Đề xuất cho bạn</option><option value="asc">Giá thấp đến cao</option><option value="desc">Giá cao đến thấp</option></select></div><MapPanel v-if="showMap" label="Khu vực tìm kiếm" :address="district||'Cần Thơ'"/><div v-if="results.length" class="room-grid search-results"><RoomCard v-for="room in results" :key="room.id" :room="room"/></div><div v-else class="empty-state"><span class="empty-icon"><Icon name="search" :size="38"/></span><h2>Chưa tìm thấy phòng phù hợp</h2><p>Thử mở rộng khu vực hoặc thay đổi khoảng giá nhé.</p><button class="button primary" @click="reset">Xóa bộ lọc</button></div></section></div></div></template>
